SET default_transaction_read_only = on;
-- #720 §7: the five folded reviews' own predicate counts, printed on the page so their bars stay visible.
\copy (SELECT 'bracket_geometry_variants_parked' AS review, COUNT(*) AS n FROM mi_live_trades WHERE account_mode = 'live' AND signal_type = 'magna53' AND status = 'closed' AND alert_date >= DATE '2026-08-17' UNION ALL SELECT 'live_fill_counterfactuals_first_read_482', COUNT(*) FROM (SELECT trade_id FROM mi_live_fill_counterfactuals WHERE account_mode = 'live' AND signal_type = 'magna53' AND exit_era = 'era_e' AND alert_date >= DATE '2026-10-13' AND arm IN ('live_actual', 'live_replay') AND outcome = 'settled' GROUP BY trade_id HAVING COUNT(DISTINCT arm) = 2) c UNION ALL SELECT 'exit_tune_cohort_review (closes)', COUNT(*) FROM mi_live_trades WHERE account_mode = 'live' AND status = 'closed' AND created_at >= DATE '2026-10-13' UNION ALL SELECT 'runner_rule_sweep_recut (trade arm)', COUNT(*) FROM mi_live_trades WHERE status = 'closed' AND risk_dollars > 0 AND account_mode = 'live' AND signal_type = 'magna53' AND created_at >= DATE '2026-10-13' UNION ALL SELECT 'stop_too_wide_outcome_cohort', COUNT(*) FROM mi_live_trades WHERE skip_reason LIKE 'setup:stop_too_wide%' AND signal_type = 'magna53' AND alert_date >= DATE '2026-05-05' AND alert_date <= CURRENT_DATE - INTERVAL '25 days') TO STDOUT WITH CSV HEADER
